import re, sys
from dataclasses import dataclass

# ============================== TERM LANGUAGE ================================
@dataclass(frozen=True)
class Var:  name: str
@dataclass(frozen=True)
class Zero: pass
@dataclass(frozen=True)
class Add:  a: object; b: object
@dataclass(frozen=True)
class Sub:  a: object; b: object
@dataclass(frozen=True)
class Sum:  v: object
@dataclass(frozen=True)
class Elem: a: object; b: object
@dataclass(frozen=True)
class Cons: h: object; t: object
@dataclass(frozen=True)
class Nil:  pass
@dataclass(frozen=True)
class Eq:   l: object; r: object
@dataclass(frozen=True)
class Claim: text: str

class RuleError(Exception): pass

def show(t):
    if isinstance(t, Var):   return t.name
    if isinstance(t, Zero):  return "0"
    if isinstance(t, Nil):   return "nil"
    if isinstance(t, Add):   return "(%s + %s)" % (show(t.a), show(t.b))
    if isinstance(t, Sub):   return "(%s - %s)" % (show(t.a), show(t.b))
    if isinstance(t, Sum):   return "sum(%s)"   % show(t.v)
    if isinstance(t, Elem):  return "eltsub(%s,%s)" % (show(t.a), show(t.b))
    if isinstance(t, Cons):  return "cons(%s,%s)"   % (show(t.h), show(t.t))
    if isinstance(t, Claim): return t.text
    raise TypeError(t)

# ============================== KERNEL =======================================
class Thm:
    __slots__ = ("l", "r", "rule", "hyps")
    def __init__(self, l, r, rule, hyps=frozenset()):
        self.l, self.r, self.rule, self.hyps = l, r, rule, hyps
    def __repr__(self):
        if isinstance(self.l, Claim): return "⊢ " + self.l.text
        return "⊢ %s = %s" % (show(self.l), show(self.r))

def _h(*ts):
    s = set()
    for t in ts: s |= set(t.hyps)
    return frozenset(s)

def REFL(t):        return Thm(t, t, "refl")
def SYM(th):        return Thm(th.r, th.l, "sym", th.hyps)
def TRANS(t1, t2):
    if t1.r != t2.l: raise RuleError("TRANS: %s vs %s" % (show(t1.r), show(t2.l)))
    return Thm(t1.l, t2.r, "trans", _h(t1, t2))
def ADD_CONG(a,b):  return Thm(Add(a.l,b.l), Add(a.r,b.r), "add_cong", _h(a,b))
def SUB_CONG(a,b):  return Thm(Sub(a.l,b.l), Sub(a.r,b.r), "sub_cong", _h(a,b))
def SUM_CONG(a):    return Thm(Sum(a.l), Sum(a.r), "sum_cong", _h(a))
def DEF_SUM_NIL():      return Thm(Sum(Nil()), Zero(), "def_sum_nil")
def DEF_SUM_CONS(x,xs): return Thm(Sum(Cons(x,xs)), Add(x, Sum(xs)), "def_sum_cons")
def DEF_ELEM_NIL():     return Thm(Elem(Nil(),Nil()), Nil(), "def_elem_nil")
def DEF_ELEM_CONS(x,xs,y,ys):
    return Thm(Elem(Cons(x,xs),Cons(y,ys)), Cons(Sub(x,y), Elem(xs,ys)), "def_elem_cons")
def ASSUME(l,r):    return Thm(l, r, "assume", frozenset({Eq(l,r)}))

def _norm(t):
    if isinstance(t, Zero): return {}
    if isinstance(t, Add):
        d = dict(_norm(t.a))
        for k,v in _norm(t.b).items(): d[k] = d.get(k,0) + v
        return d
    if isinstance(t, Sub):
        d = dict(_norm(t.a))
        for k,v in _norm(t.b).items(): d[k] = d.get(k,0) - v
        return d
    return {t: 1}
def ABGRP(l, r):
    c = lambda d: {k:v for k,v in d.items() if v}
    if c(_norm(l)) != c(_norm(r)):
        raise RuleError("ABGRP fails: %s vs %s" % (_norm(l), _norm(r)))
    return Thm(l, r, "ax_abgrp")

# ---------------------- THE FIXED INDUCT RULE --------------------------------
def INDUCT(base, step):
    if base.hyps:
        raise RuleError("INDUCT: base must be closed, got %s" % base.hyps)
    if not (isinstance(base.l, Sum) and isinstance(base.l.v, Elem)
            and base.l.v.a == Nil() and base.l.v.b == Nil()
            and base.r == Sub(Sum(Nil()), Sum(Nil()))):
        raise RuleError("INDUCT: base must be the nil,nil case")
    c = step.l
    if not (isinstance(c, Sum) and isinstance(c.v, Elem)
            and isinstance(c.v.a, Cons) and isinstance(c.v.b, Cons)):
        raise RuleError("INDUCT: step must be the cons,cons case")
    x, xs = c.v.a.h, c.v.a.t
    y, ys = c.v.b.h, c.v.b.t
    if step.r != Sub(Sum(Cons(x,xs)), Sum(Cons(y,ys))):
        raise RuleError("INDUCT: step conclusion mismatch")
    ih = Eq(Sum(Elem(xs,ys)), Sub(Sum(xs), Sum(ys)))
    # === FIX: demand EXACTLY the IH and nothing else ===
    if step.hyps != frozenset({ih}):
        raise RuleError("INDUCT: step hypotheses must be exactly {%s}, got %s"
                        % (show(ih.l), step.hyps))
    return Thm(Claim("forall a b : vector(R), len(a) = len(b) => "
                     "sum(eltsub(a,b)) = sum(a) - sum(b)"),
               Claim("same"), "induct")   # hyps = frozenset(): legitimate, IH discharged

# ============================== PROOF BUILDERS ===============================
x, xs, y, ys = Var("x"), Var("xs"), Var("y"), Var("ys")
IH = Eq(Sum(Elem(xs,ys)), Sub(Sum(xs), Sum(ys)))

def build_base():
    return TRANS(TRANS(SUM_CONG(DEF_ELEM_NIL()), DEF_SUM_NIL()),
                 TRANS(ABGRP(Zero(), Sub(Zero(),Zero())),
                       SYM(SUB_CONG(DEF_SUM_NIL(), DEF_SUM_NIL()))))

def build_step(ih_thm):
    refl_xy = REFL(Sub(x,y))
    sh1 = SUM_CONG(DEF_ELEM_CONS(x,xs,y,ys))
    h2  = DEF_SUM_CONS(Sub(x,y), Elem(xs,ys))
    lhs = TRANS(TRANS(sh1,h2), ADD_CONG(refl_xy, ih_thm))
    rhs = SUB_CONG(DEF_SUM_CONS(x,xs), DEF_SUM_CONS(y,ys))
    leaf= ABGRP(Add(Sub(x,y), Sub(Sum(xs),Sum(ys))),
                Sub(Add(x,Sum(xs)), Add(y,Sum(ys))))
    return TRANS(lhs, TRANS(leaf, SYM(rhs)))

base = build_base()

# ============================== TEST 1: honest proof =========================
print("=" * 74); print("TEST 1  —  honest certificate (step carries exactly the IH)")
print("=" * 74)
step_ok = build_step(ASSUME(Sum(Elem(xs,ys)), Sub(Sum(xs),Sum(ys))))
print("  step hyps :", step_ok.hyps)
try:
    final = INDUCT(base, step_ok)
    print("  INDUCT    : ACCEPTED  ->", final.l.text)
    print("  final hyps:", final.hyps)
    print("  STATUS    : ✅ claim verified, 0 open hypotheses")
except RuleError as e:
    print("  REJECTED  :", e)

