print("=" * 74)
w = Var("w")
bad    = ASSUME(w, Sum(Elem(xs,ys)))
maxih  = TRANS(SYM(bad), TRANS(bad, ASSUME(Sum(Elem(xs,ys)), Sub(Sum(xs),Sum(ys)))))
print("  extra hypothesis injected:", show(bad.l), "=", show(bad.r))
print("  hacked IH hyps           :", len(maxih.hyps), "hypotheses")
try:
    INDUCT(base, build_step(maxih))
    print("  INDUCT    : ACCEPTED (!!)  ->  kernel is UNSOUND")
except RuleError as e:
    print("  INDUCT    : REJECTED  ->", e)
    print("  STATUS    : ✅ hole closed")

