print(); print("=" * 74); print("TEST 3  —  wrong-conclusion induction is also caught")
print("=" * 74)
bogus = Thm(Sum(Elem(Nil(),Nil())), Sub(Sum(Nil()), Sum(Nil())), "x", frozenset())
